package com.crm.hr;
import com.crm.hr.service.*;import com.crm.hr.repository.*;import com.crm.security.AuthenticatedUserPrincipal;import org.junit.jupiter.api.*;import java.util.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;
class LeaveBalanceOwnershipTest {
 final LeaveBalanceRepository repository=mock(LeaveBalanceRepository.class);final LeaveAccess access=mock(LeaveAccess.class);final EmployeeReferenceValidator employees=mock(EmployeeReferenceValidator.class);final LeaveBalanceService service=new LeaveBalanceService(repository,access,employees);
 static UsernamePasswordAuthenticationToken auth(String role){var roles=List.of(new SimpleGrantedAuthority("ROLE_"+role));return new UsernamePasswordAuthenticationToken(new AuthenticatedUserPrincipal(42,"synthetic",roles),null,roles);}
 @BeforeEach void setup(){when(access.authentication()).thenReturn(auth("EMPLOYEE"));when(access.ownEmployeeId()).thenReturn("101");}
 @Test void ownUsesServerAssociationOnly(){service.own(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO);verify(repository).requests(eq("101"),any(),any(),any());verify(repository).quotas(eq("101"),any(),any(),any());verifyNoInteractions(employees);}
 @Test void clientCannotReadBalance(){when(access.authentication()).thenReturn(auth("CLIENT"));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.own(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO));verifyNoInteractions(repository);}
 @Test void missingAssociationDoesNotReadAnotherEmployee(){when(access.ownEmployeeId()).thenThrow(new org.springframework.security.access.AccessDeniedException("No association"));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.own(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO));verifyNoInteractions(repository);}
 @Test void adminIsCheckedBeforeDirectoryAndRead(){doThrow(new org.springframework.security.access.AccessDeniedException("Not admin")).when(access).requireAdmin();assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.administration("999",LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO,"Bearer synthetic"));verifyNoInteractions(repository,employees);}
 @Test void adminChecksRemoteReferenceThenReadsSelectedEmployee(){service.administration("999",LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO,"Bearer synthetic");var order=inOrder(access,employees,repository);order.verify(access).requireAdmin();order.verify(employees).requireExists("999","Bearer synthetic");order.verify(repository).requests(eq("999"),any(),any(),any());}
 @Test void excessiveDetailIsRejectedInsteadOfTruncated(){when(repository.requests(any(),any(),any(),any())).thenReturn(Collections.nCopies(2001,LeaveBalanceCalculationTest.row(1,"2026-01-01","2026-01-01",com.crm.hr.entity.LeaveRequest.LeaveStatus.APPROVED)));assertThrows(IllegalArgumentException.class,()->service.own(LeaveBalanceCalculationTest.FROM,LeaveBalanceCalculationTest.TO));}
}